{
  "version": 1,
  "max_steps": 30,
  "retries": 1,
  "nodes": {
    "implement": {
      "kind": "agent",
      "provider": "claude",
      "instruction": "Read the GitHub Issue identified by run_input in github_repository using available tools, then implement it completely in the assigned worktree. Run relevant tests. Do not push, open pull requests, or comment.",
      "model": "claude-opus-5-5",
      "effort": "high",
      "permission_mode": "auto"
    },
    "publish": {
      "kind": "agent",
      "provider": "claude",
      "retries": 0,
      "instruction": "Create the pull request for the Issue identified by run_input in github_repository, or update it if inputs[0].data.pr already identifies one, so that its head contains this worktree's changes. Follow the repository's conventions and pull request template for the branch, title and body, and link the Issue. Do not merge. Return the PR identity.",
      "schema": {
        "type": "object",
        "properties": {
          "pr": {
            "type": "object",
            "description": "The pull request this Run publishes; forward it unchanged unless it changes.",
            "properties": {
              "number": {
                "type": "integer"
              },
              "url": {
                "type": "string"
              },
              "head_sha": {
                "type": "string",
                "description": "Commit SHA currently at the PR head on GitHub."
              }
            },
            "required": [
              "number",
              "url",
              "head_sha"
            ],
            "additionalProperties": false
          }
        },
        "required": [
          "pr"
        ],
        "additionalProperties": false
      },
      "model": "claude-opus-5-5",
      "effort": "high",
      "permission_mode": "auto"
    },
    "review": {
      "kind": "agent",
      "provider": "claude",
      "instruction": "Review the pull request in inputs[0].data.pr against the Issue identified by run_input: check both missing scope and unnecessary scope, correctness, and tests. Leave files unchanged; do not push or merge. Forward pr unchanged.",
      "schema": {
        "type": "object",
        "properties": {
          "pr": {
            "type": "object",
            "description": "The pull request this Run publishes; forward it unchanged unless it changes.",
            "properties": {
              "number": {
                "type": "integer"
              },
              "url": {
                "type": "string"
              },
              "head_sha": {
                "type": "string",
                "description": "Commit SHA currently at the PR head on GitHub."
              }
            },
            "required": [
              "number",
              "url",
              "head_sha"
            ],
            "additionalProperties": false
          },
          "approved": {
            "type": "boolean",
            "description": "True only when no blocking review findings remain."
          },
          "findings": {
            "type": "array",
            "description": "Blocking problems that must be fixed before approval.",
            "items": {
              "type": "string"
            }
          }
        },
        "required": [
          "pr",
          "approved",
          "findings"
        ],
        "additionalProperties": false
      },
      "model": "claude-opus-5-5",
      "effort": "high",
      "permission_mode": "auto"
    },
    "fix": {
      "kind": "agent",
      "provider": "claude",
      "instruction": "Fix the findings in inputs[0].data.findings in the assigned worktree and run relevant tests. Do not push or merge. Forward inputs[0].data.pr unchanged and summarize the fixes.",
      "schema": {
        "type": "object",
        "properties": {
          "pr": {
            "type": "object",
            "description": "The pull request this Run publishes; forward it unchanged unless it changes.",
            "properties": {
              "number": {
                "type": "integer"
              },
              "url": {
                "type": "string"
              },
              "head_sha": {
                "type": "string",
                "description": "Commit SHA currently at the PR head on GitHub."
              }
            },
            "required": [
              "number",
              "url",
              "head_sha"
            ],
            "additionalProperties": false
          },
          "summary": {
            "type": "string"
          }
        },
        "required": [
          "pr",
          "summary"
        ],
        "additionalProperties": false
      },
      "model": "claude-opus-5-5",
      "effort": "high",
      "permission_mode": "auto"
    },
    "merge": {
      "kind": "agent",
      "provider": "claude",
      "retries": 0,
      "instruction": "Merge the pull request in inputs[0].data.pr only if its head is still inputs[0].data.pr.head_sha, following repository conventions and GitHub policy. Do not bypass required checks or reviews. Forward pr.",
      "schema": {
        "type": "object",
        "properties": {
          "pr": {
            "type": "object",
            "description": "The pull request this Run publishes; forward it unchanged unless it changes.",
            "properties": {
              "number": {
                "type": "integer"
              },
              "url": {
                "type": "string"
              },
              "head_sha": {
                "type": "string",
                "description": "Commit SHA currently at the PR head on GitHub."
              }
            },
            "required": [
              "number",
              "url",
              "head_sha"
            ],
            "additionalProperties": false
          },
          "merged": {
            "type": "boolean"
          },
          "merge_commit": {
            "type": "string",
            "description": "Merge commit SHA; omit when not merged."
          }
        },
        "required": [
          "pr",
          "merged"
        ],
        "additionalProperties": false
      },
      "model": "claude-opus-5-5",
      "effort": "high",
      "permission_mode": "auto"
    },
    "close_issue": {
      "kind": "agent",
      "provider": "claude",
      "retries": 0,
      "instruction": "If inputs[0].data.merged is true, make sure the Issue identified by run_input in github_repository is closed, referencing the merged pull request in inputs[0].data.pr. Otherwise leave it open. Report whether it is closed.",
      "schema": {
        "type": "object",
        "properties": {
          "closed": {
            "type": "boolean"
          }
        },
        "required": [
          "closed"
        ],
        "additionalProperties": false
      },
      "model": "claude-opus-5-5",
      "effort": "high",
      "permission_mode": "auto"
    }
  },
  "flow": [
    "implement",
    "publish",
    "review",
    {
      "loop": {
        "flow": [
          {
            "if": {
              "condition": {
                "path": "/0/data/approved",
                "equals": true
              },
              "then": [],
              "else": [
                "fix",
                "publish",
                "review"
              ]
            }
          }
        ],
        "while": {
          "path": "/0/data/approved",
          "equals": false
        }
      }
    },
    "merge",
    "close_issue"
  ]
}
